def identity(p):
 p=R/p;return {'path':str(p.relative_to(R)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
def gate(name):
 p=f'selfhost/build/phase22/{name}/report.json';x=read(p)
 assert x['complete'] and x['exactAgreement'] and x['selected']['exactDifferences']==0
